-- ===== 0. the test trip, the two people ==========================================================================================
DO $rh$
DECLARE
  v_trip constant uuid := 'be551bc4-a524-4b6a-a0c9-b74a7168ced4';
  v_a uuid; v_b uuid;
BEGIN
  BEGIN
    SELECT t.created_by INTO v_a FROM public.trips t WHERE t.id = v_trip;
    IF NOT FOUND THEN PERFORM pg_temp.rh_rec('setup.trip', false, 'test trip not found'); RETURN; END IF;
    SELECT tp.user_id INTO v_b FROM public.trip_participants tp WHERE tp.trip_id = v_trip AND tp.user_id <> v_a AND coalesce(tp.active, true) ORDER BY tp.user_id LIMIT 1;
    INSERT INTO _rh_ctx VALUES ('trip', v_trip::text), ('a', v_a::text);
    IF v_b IS NOT NULL THEN INSERT INTO _rh_ctx VALUES ('b', v_b::text); END IF;
    PERFORM pg_temp.rh_rec('setup.trip', v_a IS NOT NULL AND v_b IS NOT NULL, 'A = creator, B = another participant');
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('setup.trip', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== 1. structure ===========================================================================================================================
DO $rh$
DECLARE
  v_bad text := ''; r record;
BEGIN
  BEGIN
    PERFORM pg_temp.rh_rec('struct.restrictive_policies', (SELECT count(*) FROM pg_policies WHERE tablename = 'trip_chat_messages' AND permissive = 'RESTRICTIVE' AND policyname LIKE 'Private chat threads:%') = 4
      AND (SELECT count(*) FROM pg_policies WHERE tablename = 'chat_actions') = 1 AND (SELECT count(*) FROM pg_policies WHERE tablename = 'trip_chat_threads') = 1, '4 restrictive policies on trip_chat_messages; 1 select policy each on chat_actions and trip_chat_threads');
    PERFORM pg_temp.rh_rec('struct.table_privileges', has_table_privilege('authenticated', 'public.chat_actions', 'SELECT') AND NOT has_table_privilege('authenticated', 'public.chat_actions', 'INSERT')
      AND NOT has_table_privilege('authenticated', 'public.chat_actions', 'UPDATE') AND NOT has_table_privilege('authenticated', 'public.chat_actions', 'DELETE') AND NOT has_table_privilege('anon', 'public.chat_actions', 'SELECT')
      AND has_table_privilege('authenticated', 'public.trip_chat_threads', 'SELECT') AND NOT has_table_privilege('authenticated', 'public.trip_chat_threads', 'INSERT'), 'clients: SELECT only on chat_actions and trip_chat_threads');
    FOR r IN SELECT * FROM (VALUES
      ('public.begin_chat_action(uuid)', true, null), ('public.finish_chat_action(uuid,boolean,jsonb,text)', true, null), ('public.dismiss_chat_action(uuid)', true, null),
      ('public.mark_chat_action_edited(uuid,jsonb)', true, null), ('public.mark_chat_action_undone(uuid)', true, null), ('public.new_chat(uuid)', true, null), ('public.mark_chat_seen(uuid)', true, null), ('public.admin_ai_usage_summary(integer)', true, null),
      ('public.chat_actions_expire_stale()', false, null), ('public._chat_action_own(uuid)', false, null), ('public.guard_chat_action_update()', false, null)
    ) AS x(f, want_auth, w) LOOP
      IF has_function_privilege('anon', r.f, 'EXECUTE') OR has_function_privilege('authenticated', r.f, 'EXECUTE') IS DISTINCT FROM r.want_auth THEN v_bad := v_bad || r.f || ' '; END IF;
    END LOOP;
    PERFORM pg_temp.rh_rec('struct.function_privileges', v_bad = '', CASE WHEN v_bad = '' THEN '11 functions as intended' ELSE 'wrong: ' || v_bad END);
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('struct', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== 2. private threads ======================================================================================================================
DO $rh$
DECLARE
  v_trip uuid := pg_temp.rh_ctx('trip')::uuid; v_a uuid := pg_temp.rh_ctx('a')::uuid; v_b uuid := pg_temp.rh_ctx('b')::uuid;
  v_legacy integer := pg_temp.rh_ctx('legacy_rows')::integer; v_turn uuid := gen_random_uuid(); v_n integer; v_na integer; v_nb integer; v_visible_legacy integer; v_code text;
BEGIN
  IF v_a IS NULL OR v_b IS NULL THEN RETURN; END IF;
  BEGIN
    -- the edge function (service role / owner) writes both rows of a turn into the asker's thread
    INSERT INTO public.trip_chat_messages (trip_id, user_id, role, content, thread_user_id, turn_id) VALUES (v_trip, v_a, 'user', 'REHEARSAL A question', v_a, v_turn);
    INSERT INTO public.trip_chat_messages (trip_id, user_id, role, content, thread_user_id, turn_id) VALUES (v_trip, NULL, 'assistant', 'REHEARSAL answer to A', v_a, v_turn);
    INSERT INTO public.trip_chat_messages (trip_id, user_id, role, content, thread_user_id) VALUES (v_trip, v_b, 'user', 'REHEARSAL B question', v_b);
    SELECT count(*) INTO v_visible_legacy FROM public.trip_chat_messages WHERE trip_id = v_trip AND thread_user_id IS NULL;
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    SELECT count(*) INTO v_na FROM public.trip_chat_messages WHERE trip_id = v_trip;
    SELECT count(*) INTO v_n FROM public.trip_chat_messages WHERE trip_id = v_trip AND content LIKE 'REHEARSAL B%';
    RESET ROLE;
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    SELECT count(*) INTO v_nb FROM public.trip_chat_messages WHERE trip_id = v_trip;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('threads.private', v_n = 0 AND v_na = v_visible_legacy + 2 AND v_nb = v_visible_legacy + 1,
      format('A sees %s rows (legacy %s + her 2), B sees %s (legacy + his 1), A sees none of B''s; legacy rows before: %s', v_na, v_visible_legacy, v_nb, v_legacy));
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('threads.private', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
  BEGIN
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    INSERT INTO public.trip_chat_messages (trip_id, user_id, role, content, thread_user_id) VALUES (v_trip, v_b, 'user', 'REHEARSAL forged legacy', NULL);
    RESET ROLE;
    PERFORM pg_temp.rh_rec('threads.client_cannot_forge_legacy', false, 'NOT refused');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('threads.client_cannot_forge_legacy', SQLSTATE = '42501', SQLSTATE || ' ' || left(SQLERRM, 80));
  END;
  BEGIN
    INSERT INTO public.trip_chat_messages (trip_id, user_id, role, content, thread_user_id, turn_id) VALUES (v_trip, v_a, 'user', 'REHEARSAL duplicate turn', v_a, v_turn);
    PERFORM pg_temp.rh_rec('threads.turn_dedupe', false, 'NOT refused');
  EXCEPTION WHEN unique_violation THEN
    PERFORM pg_temp.rh_rec('threads.turn_dedupe', true, '23505 for the same (trip, thread, turn, role)');
  WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('threads.turn_dedupe', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
  BEGIN
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    PERFORM public.new_chat(v_trip);
    PERFORM public.mark_chat_seen(v_trip);
    SELECT count(*) INTO v_n FROM public.trip_chat_threads WHERE trip_id = v_trip;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('threads.new_chat', v_n = 1 AND (SELECT cleared_at IS NOT NULL FROM public.trip_chat_threads WHERE trip_id = v_trip AND user_id = v_a), 'new_chat + mark_chat_seen by A: one thread-state row, cleared_at set');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('threads.new_chat', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== 3. chat_actions: owner-only state machine, run once, client cannot insert or alter, daily cap =====================================================
DO $rh$
DECLARE
  v_trip uuid := pg_temp.rh_ctx('trip')::uuid; v_a uuid := pg_temp.rh_ctx('a')::uuid; v_b uuid := pg_temp.rh_ctx('b')::uuid;
  v_id uuid; v_id2 uuid; v_r jsonb; v_r2 jsonb; v_r3 jsonb; v_r4 jsonb; v_r5 jsonb; v_hint text; v_i integer; v_n integer; v_cnt integer := 0;
BEGIN
  IF v_a IS NULL OR v_b IS NULL THEN RETURN; END IF;
  -- the edge function (service role / owner) stores two proposals for A
  INSERT INTO public.chat_actions (trip_id, user_id, turn_id, kind, params, preview, basis, requires) VALUES (v_trip, v_a, gen_random_uuid(), 'add_todo', '{"title":"REHEARSAL"}', '{}', '{}', 'tap') RETURNING id INTO v_id;
  INSERT INTO public.chat_actions (trip_id, user_id, turn_id, kind, params, preview, basis, requires) VALUES (v_trip, v_a, gen_random_uuid(), 'answer', '{}', '{}', '{}', 'review') RETURNING id INTO v_id2;
  BEGIN
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    PERFORM public.begin_chat_action(v_id);
    RESET ROLE;
    PERFORM pg_temp.rh_rec('actions.other_person_refused', false, 'NOT refused');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    PERFORM pg_temp.rh_rec('actions.other_person_refused', v_hint = 'not_found', SQLSTATE || ' hint=' || coalesce(v_hint, ''));
  END;
  BEGIN
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    v_r := public.begin_chat_action(v_id);
    v_r2 := public.begin_chat_action(v_id);
    v_r3 := public.finish_chat_action(v_id, true, '{"todo_id":"x"}');
    v_r5 := public.mark_chat_action_undone(v_id);
    v_r4 := public.dismiss_chat_action(v_id2);
    SELECT count(*) INTO v_n FROM public.chat_actions;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('actions.begin', (v_r ->> 'started')::boolean AND v_r #>> '{action,status}' = 'executing', v_r ->> 'reason');
    PERFORM pg_temp.rh_rec('actions.begin_twice_runs_once', NOT (v_r2 ->> 'started')::boolean AND v_r2 ->> 'reason' = 'already_started', v_r2 ->> 'reason');
    PERFORM pg_temp.rh_rec('actions.finish', (v_r3 ->> 'finished')::boolean AND v_r3 #>> '{action,status}' = 'done', v_r3 #>> '{action,status}');
    PERFORM pg_temp.rh_rec('actions.undone', (v_r5 ->> 'undone')::boolean AND v_r5 #> '{action,result,undone_at}' IS NOT NULL, v_r5 #>> '{action,result}');
    PERFORM pg_temp.rh_rec('actions.dismiss', (v_r4 ->> 'dismissed')::boolean, v_r4 #>> '{action,status}');
    PERFORM pg_temp.rh_rec('actions.client_reads_own_only', v_n >= 2, 'A reads her proposals: ' || v_n);
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('actions.begin', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
  BEGIN
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    INSERT INTO public.chat_actions (trip_id, user_id, turn_id, kind, params, preview, basis, requires) VALUES (v_trip, v_a, gen_random_uuid(), 'x1', '{}', '{}', '{}', 'tap');
    RESET ROLE;
    PERFORM pg_temp.rh_rec('actions.client_cannot_insert', false, 'NOT refused');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('actions.client_cannot_insert', SQLSTATE = '42501', SQLSTATE || ' ' || left(SQLERRM, 80));
  END;
  BEGIN
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    UPDATE public.chat_actions SET params = '{"title":"EVIL"}' WHERE id = v_id;
    RESET ROLE;
    PERFORM pg_temp.rh_rec('actions.client_cannot_alter', false, 'NOT refused');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('actions.client_cannot_alter', SQLSTATE = '42501', SQLSTATE || ' ' || left(SQLERRM, 80));
  END;
  -- the daily cap: 25 confirmed actions in 24h
  BEGIN
    FOR v_i IN 1..26 LOOP
      INSERT INTO public.chat_actions (trip_id, user_id, turn_id, kind, params, preview, basis, requires) VALUES (v_trip, v_b, gen_random_uuid(), 'add_todo', '{}', '{}', '{}', 'tap') RETURNING id INTO v_id;
      PERFORM pg_temp.rh_jwt(v_b);
      SET LOCAL ROLE authenticated;
      PERFORM public.begin_chat_action(v_id);
      RESET ROLE;
      v_cnt := v_cnt + 1;
    END LOOP;
    PERFORM pg_temp.rh_rec('actions.daily_cap', false, '26th NOT refused');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    PERFORM pg_temp.rh_rec('actions.daily_cap', v_hint = 'daily_cap' AND v_cnt = 25, format('25 started, the 26th refused with hint=%s (started=%s)', coalesce(v_hint, ''), v_cnt));
  END;
END
$rh$;

-- ===== 4. admin usage summary (site admins only) =====================================================================================================
DO $rh$
DECLARE
  v_a uuid := pg_temp.rh_ctx('a')::uuid; v_b uuid := pg_temp.rh_ctx('b')::uuid; v_r jsonb; v_hint text;
BEGIN
  IF v_a IS NULL OR v_b IS NULL THEN RETURN; END IF;
  UPDATE public.users SET role = 'member' WHERE id = v_b;     -- inside the transaction only (rolled back)
  UPDATE public.users SET role = 'admin' WHERE id = v_a;
  BEGIN
    PERFORM pg_temp.rh_jwt(v_b);
    SET LOCAL ROLE authenticated;
    PERFORM public.admin_ai_usage_summary(30);
    RESET ROLE;
    PERFORM pg_temp.rh_rec('admin.member_refused', false, 'NOT refused');
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    PERFORM pg_temp.rh_rec('admin.member_refused', v_hint = 'forbidden', SQLSTATE || ' hint=' || coalesce(v_hint, ''));
  END;
  BEGIN
    PERFORM pg_temp.rh_jwt(v_a);
    SET LOCAL ROLE authenticated;
    v_r := public.admin_ai_usage_summary(30);
    RESET ROLE;
    PERFORM pg_temp.rh_rec('admin.summary', jsonb_typeof(v_r -> 'usage') = 'array' AND jsonb_typeof(v_r -> 'actions') = 'array' AND (v_r ->> 'days')::int = 30,
      format('usage rows=%s, action kinds=%s', jsonb_array_length(v_r -> 'usage'), jsonb_array_length(v_r -> 'actions')));
  EXCEPTION WHEN OTHERS THEN
    RESET ROLE;
    PERFORM pg_temp.rh_rec('admin.summary', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== FINAL: report through the error message (this also rolls everything back) ===============================================================================
DO $rh$
DECLARE
  v_all boolean; v_json text; v_failed integer; v_total integer;
BEGIN
  SELECT coalesce(bool_and(ok), false), count(*) FILTER (WHERE NOT ok), count(*) INTO v_all, v_failed, v_total FROM _rehearsal;
  SELECT coalesce(jsonb_agg(jsonb_build_object('step', step, 'ok', ok, 'detail', left(detail, 160)) ORDER BY ok, ctid), '[]'::jsonb)::text INTO v_json FROM _rehearsal;
  IF length(v_json) > 6000 THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('step', step, 'ok', ok, 'detail', left(detail, CASE WHEN ok THEN 0 ELSE 90 END)) ORDER BY ok, ctid), '[]'::jsonb)::text INTO v_json FROM _rehearsal;
  END IF;
  IF length(v_json) > 6000 THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('step', step, 'ok', ok, 'detail', left(detail, 90)) ORDER BY ok, ctid), '[]'::jsonb)::text INTO v_json FROM _rehearsal WHERE NOT ok;
    v_json := left(v_json, 5800) || ' (only failing steps shown)';
  END IF;
  RAISE EXCEPTION '%', 'REHEARSAL ' || CASE WHEN v_all THEN 'PASS' ELSE 'FAIL' END || ' (' || v_total || ' steps, ' || v_failed || ' failed) ' || v_json;
END
$rh$;
ROLLBACK;
